import pyomo.environ as pyo

DATA = {
    "products": ["A", "B", "C"],
    "resources": {
        "tech":  {"avail": 100},
        "labor": {"avail": 700},
        "mat":   {"avail": 400},
    },
    "usage": {
        "A": {"tech": 1, "labor": 10, "mat": 3},
        "B": {"tech": 2, "labor":  4, "mat": 2},
        "C": {"tech": 1, "labor":  5, "mat": 1},
    },
    # Brackets: list of (upper_bound_units, profit_per_unit)
    "brackets": {
        "A": [(40, 10), (100, 9), (150, 8), (None, 7)],
        "B": [(50, 6), (100, 4), (None, 3)],
        "C": [(100, 5), (None, 4)],
    },
    "M": 10000,
}


def build_model(data=None):
    d = data or DATA
    products = d["products"]
    brackets  = d["brackets"]
    M = d["M"]

    # Index set of (product, bracket-number)
    bracket_index = [(p, k) for p in products for k in range(len(brackets[p]))]

    model = pyo.ConcreteModel()
    model.P = pyo.Set(initialize=products, ordered=True)
    model.BI = pyo.Set(initialize=bracket_index, ordered=True, dimen=2)
    model.R = pyo.Set(initialize=list(d["resources"].keys()))

    # ---- Variables ----
    def x_bounds(m, p):
        return (0, None)
    model.x = pyo.Var(model.P, domain=pyo.NonNegativeIntegers, bounds=x_bounds)

    def y_bounds(m, p, k):
        return (0, _bracket_width(brackets, p, k))
    model.y = pyo.Var(model.BI, domain=pyo.NonNegativeIntegers, bounds=y_bounds)

    model.z = pyo.Var(model.BI, domain=pyo.Binary)

    # ---- Objective: maximize total profit ----
    def profit_expr(m):
        return sum(brackets[p][k][1] * m.y[p, k] for (p, k) in m.BI)
    model.obj = pyo.Objective(expr=profit_expr(model), sense=pyo.maximize)

    # ---- Resource-capacity constraints: one rule per resource ----
    def resource_rule(m, r):
        return sum(d["usage"][p][r] * m.x[p] for p in m.P) <= d["resources"][r]["avail"]
    model.capacity = pyo.Constraint(model.R, rule=resource_rule)

    # ---- Volume accounting: sales of each product fill its brackets ----
    def accounting_rule(m, p):
        return m.x[p] == sum(m.y[p, k] for k in range(len(brackets[p])))
    model.accounting = pyo.Constraint(model.P, rule=accounting_rule)

    # ---- Per-bracket volume cap: y[p,k] <= width[p,k] * z[p,k] ----
    def bracket_cap_rule(m, p, k):
        w = _bracket_width(brackets, p, k)
        return m.y[p, k] <= w * m.z[p, k]
    model.bracket_cap = pyo.Constraint(model.BI, rule=bracket_cap_rule)

    # ---- Sequencing: a later bracket cannot be used unless the prior one is filled ----
    # z[p,k] <= z[p,k-1]  for k >= 1  (monotone, top-most active bracket is k)
    def sequence_rule(m, p, k):
        return m.z[p, k] <= m.z[p, k - 1]
    model.sequence = pyo.Constraint(
        [(p, k) for (p, k) in bracket_index if k >= 1], rule=sequence_rule
    )

    return model


def _bracket_width(brackets, p, k):
    """Width of bracket k for product p (units)."""
    brackets_p = brackets[p]
    prev_upper = 0 if k == 0 else brackets_p[k - 1][0]
    upper = brackets_p[k][0]
    if upper is None:
        return DATA["M"]
    return upper - prev_upper

